package com.codepilot1c.core.edt.development;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
import com.codepilot1c.core.mcp.host.McpRuntimeRouting;
public class RuntimePreparationServiceTest {
 @Rule public TemporaryFolder tmp=new TemporaryFolder();
 static final String UUID="11111111-1111-4111-8111-111111111111";
 class Fake implements RuntimePreparationService.Backend {
  int starts,envs,hosts,hostStarts;boolean refreshReady;int refreshes;boolean sync=true,connected=true,failAfterReserve,borrowed,changeDuringPython,nativeConnected;String branch="one",base=UUID;CountDownLatch entered=new CountDownLatch(1),gate=new CountDownLatch(0);List<String> cleaned=new ArrayList<>();boolean failCleanup;
  public Map<String,Object> binding(String p){return Map.of("project",p,"base_uuid",base,"configuration_synchronized",sync,"context",branch);}
  public Map<String,Object> refreshBinding(String p){refreshes++;if(refreshReady)sync=true;return binding(p);}
  public Map<String,Object> route(Map<String,Object>a){return McpRuntimeRouting.choose(a,true);}
  public Map<String,Object> environment(){return borrowed?Map.of("ready",true,"environment_id","env"):Map.of("ready",false,"state","needs_setup");}
  public Map<String,Object> prepareEnvironment(Consumer<String> r){envs++;r.accept("env");if(changeDuringPython)branch="two";return Map.of("ready",true,"environment_id","env","created",true);}
  public Map<String,Object> startClient(Map<String,Object> p,String e,Consumer<String> r)throws Exception{starts++;r.accept("client");entered.countDown();gate.await(10,TimeUnit.SECONDS);if(failAfterReserve)throw new IllegalStateException("partial start");return Map.of("client_id","client");}
  public Map<String,Object> prepareHost(Map<String,Object>a,Consumer<String> r){assertEquals("external",a.get("mode"));hosts++;r.accept("host");return Map.of("host_id","host");}
  public void startHost(String h){hostStarts++;}
  public Map<String,Object> ready(String engine,Map<String,Object>a,List<Map<String,Object>>r){return engine.equals("native")?Map.of("ready",nativeConnected,"host_id","host","state","starting"):engine.equals("vanessa")?Map.of("ready",false,"reason","runner_profile_missing"):Map.of("ready",connected,"client_id","client");}
  public Map<String,Object> cleanup(String k,String id){if(failCleanup)throw new IllegalStateException("changed resource");cleaned.add(k);return Map.of("cleaned",true);}
 }
 Fake backend;RuntimePreparationService service;Path root;
 @Before public void init()throws Exception{backend=new Fake();root=tmp.newFolder().toPath();service=new RuntimePreparationService(root,backend);}
 Map<String,Object> args(){return new LinkedHashMap<>(Map.of("project","P","base_uuid",UUID,"idempotency_key","one","intent","ui"));}
 Map<String,Object> await(String id)throws Exception{for(int i=0;i<300;i++){var s=service.status(id);if(Boolean.TRUE.equals(s.get("terminal")))return s;Thread.sleep(10);}throw new AssertionError("Preparation did not finish");}
 Map<String,Object> prepare(Map<String,Object>a)throws Exception{return await((String)service.prepare(a).get("preparation_id"));}
 @Test public void oneCallPreparesPythonAndOwnClient()throws Exception{var r=prepare(args());assertEquals("ready",r.get("state"));assertEquals(true,r.get("ready"));assertEquals(1,backend.envs);assertEquals(1,backend.starts);assertEquals(false,r.get("configuration_updated"));assertEquals(2,((List<?>)r.get("resources")).size());}
 @Test public void repeatSameKeyDoesNotReinstallOrLaunch()throws Exception{var first=prepare(args());var second=new RuntimePreparationService(root,backend).prepare(args());assertEquals(first.get("preparation_id"),second.get("preparation_id"));assertEquals(true,second.get("ready"));assertEquals(1,backend.starts);assertEquals(1,backend.envs);}
 @Test public void changedArgumentsCannotReuseKey()throws Exception{prepare(args());var a=args();a.put("intent","query");try{service.prepare(a);fail();}catch(IllegalStateException expected){}assertEquals(1,backend.starts);}
 @Test public void explicitUuidAndEqualAreCheckedBeforeAnySetup()throws Exception{backend.base="another";assertEquals("blocked",prepare(args()).get("state"));assertEquals(0,backend.envs);var a=args();a.put("idempotency_key","two");backend.base=UUID;backend.sync=false;assertEquals("needs_update",prepare(a).get("state"));assertEquals(0,backend.starts);}
 @Test public void changedContextBetweenSetupAndLaunchBlocksLaunch()throws Exception{backend.changeDuringPython=true;var r=prepare(args());assertEquals("outcome_unknown",r.get("state"));assertEquals(0,backend.starts);assertEquals(1,((List<?>)r.get("resources")).size());}
 @Test public void unknownPreviousOperationDoesNotEvenProbeBinding()throws Exception{var a=args();a.put("previous_state","outcome_unknown");assertEquals("blocked",prepare(a).get("state"));assertEquals(0,backend.envs);assertEquals(0,backend.starts);}
 @Test public void partialStartKeepsIdAndNeverRepeats()throws Exception{backend.failAfterReserve=true;var r=prepare(args());assertEquals("outcome_unknown",r.get("state"));assertEquals(2,((List<?>)r.get("resources")).size());backend.failAfterReserve=false;assertEquals("outcome_unknown",service.prepare(args()).get("state"));assertEquals(1,backend.starts);}
 @Test public void nativeNeedsPackageWithoutCreatingHost()throws Exception{var a=args();a.put("intent","query");assertEquals("needs_native_package",prepare(a).get("state"));assertEquals(0,backend.hosts);assertEquals(0,backend.envs);}
 @Test public void nativeStartOnceAndStatusOnlyObservesPendingTrust()throws Exception{var a=args();a.put("intent","query");a.put("native_path","C:/native.zip");a.put("expected_native_sha256","a".repeat(64));String id=(String)service.prepare(a).get("preparation_id");for(int i=0;i<200&&backend.hostStarts==0;i++)Thread.sleep(10);Map<String,Object> r=null;for(int i=0;i<200;i++){r=service.status(id);if("awaiting_runtime".equals(r.get("state")))break;Thread.sleep(10);}assertEquals("awaiting_runtime",r.get("state"));assertEquals(false,r.get("ready"));backend.nativeConnected=true;assertEquals(true,service.status(id).get("ready"));service.prepare(a);assertEquals(1,backend.hostStarts);}
 @Test public void readinessIsNotHistoricalReceipt()throws Exception{var r=prepare(args());backend.connected=false;assertEquals(false,service.status((String)r.get("preparation_id")).get("ready"));backend.branch="new";assertEquals("blocked",service.status((String)r.get("preparation_id")).get("state"));assertEquals(1,backend.starts);}
 @Test public void cleanupPreservesBorrowedEnvironmentAndUsesPreview()throws Exception{backend.borrowed=true;var r=prepare(args());String id=(String)r.get("preparation_id");try{service.cleanup(id,"bad");fail();}catch(IllegalStateException expected){}assertTrue(backend.cleaned.isEmpty());var p=service.cleanupPreview(id);assertEquals("cleaned",service.cleanup(id,(String)p.get("plan_sha256")).get("state"));assertEquals(List.of("testclient"),backend.cleaned);}
 @Test public void cleanupOwnedClientBeforePythonAndPreservePartial()throws Exception{var r=prepare(args());String id=(String)r.get("preparation_id");backend.failCleanup=true;var p=service.cleanupPreview(id);assertEquals("cleanup_incomplete",service.cleanup(id,(String)p.get("plan_sha256")).get("state"));backend.failCleanup=false;p=service.cleanupPreview(id);assertEquals("cleaned",service.cleanup(id,(String)p.get("plan_sha256")).get("state"));assertEquals(List.of("testclient","python_environment"),backend.cleaned);}
 @Test public void concurrentRepeatedPrepareCannotDuplicateClient()throws Exception{backend.gate=new CountDownLatch(1);String id=(String)service.prepare(args()).get("preparation_id");assertTrue(backend.entered.await(3,TimeUnit.SECONDS));assertEquals("preparing",service.prepare(args()).get("state"));try{service.cleanupPreview(id);fail();}catch(IllegalStateException expected){}backend.gate.countDown();await(id);assertEquals(1,backend.starts);}
 @Test public void restartWithClaimedJournalNeverCallsBackendAgain()throws Exception{String id="prep-"+"a".repeat(64);var doc=Map.of("preparation_id",id,"state","reserved","request",args(),"resources",List.of(Map.of("kind","testclient","id","reserved","created",true,"cleanup_state","pending")));Files.writeString(root.resolve(id+".json"),new com.google.gson.Gson().toJson(doc));var r=service.status(id);assertEquals("outcome_unknown",r.get("state"));assertEquals(0,backend.starts);}
 @Test public void missingVanessaProfileIsExplicitNotFallbackLaunch()throws Exception{var a=args();a.put("intent","scenario");var r=prepare(a);assertEquals("needs_runner_setup",r.get("state"));assertEquals(0,backend.starts);assertEquals(0,backend.envs);}
 @Test public void requestCannotAskForDatabaseUpdateOrMetadataHost()throws Exception{var a=args();a.put("mode","metadata");try{service.prepare(a);fail();}catch(IllegalArgumentException expected){}assertEquals(0,backend.hosts);}
 @Test public void unknownStartCannotBeBypassedWithNewKeyOrEngine()throws Exception{backend.failAfterReserve=true;prepare(args());var a=args();a.put("idempotency_key","replacement");a.put("intent","query");try{service.prepare(a);fail();}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("original preparation"));}assertEquals(1,backend.starts);assertEquals(0,backend.hosts);}
 @Test public void readyClientCannotBeDuplicatedWithAnotherKey()throws Exception{prepare(args());var a=args();a.put("idempotency_key","replacement");try{service.prepare(a);fail();}catch(IllegalStateException expected){}assertEquals(1,backend.starts);}
 @Test public void nativeHelperCanBePlannedAlongsideVerifiedUiClient()throws Exception{prepare(args());var a=args();a.put("idempotency_key","helper");a.put("intent","query");assertEquals("needs_native_package",prepare(a).get("state"));assertEquals(1,backend.starts);}
 @Test public void disconnectedUiCannotAuthorizeAnotherEngine()throws Exception{prepare(args());backend.connected=false;var a=args();a.put("intent","query");a.put("idempotency_key","helper-after-loss");a.put("native_path","C:/native.zip");a.put("expected_native_sha256","a".repeat(64));try{service.prepare(a);fail();}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("original preparation"));}assertEquals(0,backend.hosts);assertEquals(1,backend.starts);}
 @Test public void nativeFirstBecomesDurablyReadyAndAllowsUiAlongside()throws Exception{var a=args();a.put("intent","query");a.put("native_path","C:/native.zip");a.put("expected_native_sha256","a".repeat(64));String id=(String)service.prepare(a).get("preparation_id");for(int i=0;i<300&&!"awaiting_runtime".equals(service.status(id).get("state"));i++)Thread.sleep(10);assertEquals("awaiting_runtime",service.status(id).get("state"));backend.nativeConnected=true;assertEquals(true,service.status(id).get("ready"));var ui=args();ui.put("idempotency_key","ui-after-native");assertEquals(true,prepare(ui).get("ready"));assertEquals(1,backend.hostStarts);assertEquals(1,backend.starts);}
 @Test public void explicitPreparationDependenciesRemainCanonical(){assertEquals(Set.of("edt_infobase_state","edt_infobase_refresh","edt_test_client"),RuntimePreparationService.prepareOperations(Map.of("intent","ui","engine","testclient")));assertTrue(RuntimePreparationService.prepareOperations(Map.of("intent","query")).contains("edt_runtime_host"));}
 @Test public void staleNativeEqualityRefreshesWithoutDatabaseUpdate()throws Exception{backend.sync=false;backend.refreshReady=true;var r=prepare(args());assertEquals(true,r.get("ready"));assertEquals(1,backend.refreshes);assertEquals(1,backend.starts);assertEquals(false,r.get("configuration_updated"));}
 @Test public void preparationTimingsIncludePythonAndStartupWithoutPayloads()throws Exception{var r=prepare(args());var phases=TaskSessionService.object(r.get("phase_timings_ms"));assertTrue(phases.containsKey("preparing_python"));assertTrue(phases.containsKey("starting_testclient"));assertTrue(((Number)r.get("elapsed_ms")).longValue()>=0);assertFalse(phases.containsKey("native_path"));}
 @Test public void waitForPreparationDoesNotRestartAndReadinessStaysLive()throws Exception{String id=(String)service.prepare(args()).get("preparation_id");var result=service.waitFor(id,3000);assertEquals(true,result.get("ready"));assertEquals(false,result.get("timed_out"));backend.connected=false;assertEquals(false,service.waitFor(id,0).get("ready"));assertEquals(1,backend.starts);}
 @Test public void detailsAndWaitUseSamePermissionDependenciesAsStatus()throws Exception{String id=(String)prepare(args()).get("preparation_id");var expected=service.operations(Map.of("action","status","preparation_id",id));assertEquals(expected,service.operations(Map.of("action","wait","preparation_id",id)));assertEquals(expected,service.operations(Map.of("action","details","preparation_id",id)));}

 @Test public void nativePackageCanBePreparedAutomaticallyWithoutChangingOriginalRequest()throws Exception{backend=new Fake(){public Map<String,Object> nativePackage(){return Map.of("ready",true,"native_path","verified-cache.zip","expected_native_sha256","b".repeat(64));}};backend.nativeConnected=true;service=new RuntimePreparationService(root,backend);var a=args();a.put("intent","query");assertEquals(true,prepare(a).get("ready"));assertFalse(a.containsKey("native_path"));assertEquals(1,backend.hosts);assertEquals(1,backend.hostStarts);}
 @Test public void incompleteExplicitNativeOverrideIsRejectedBeforeSetup(){var a=args();a.put("intent","query");a.put("native_path","one.zip");assertThrows(IllegalArgumentException.class,()->service.prepare(a));assertEquals(0,backend.hosts);}

}
